(async()=>{assert(fs.existsSync('dist/fonts/manrope.ttf'));assert.equal(fs.statSync('dist/fonts/manrope.ttf').size,165420);const b=await chromium.launch({headless:true,channel:'msedge'});try{const p=await b.newPage({viewport:{width:1968,height:980}});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>{window.numberFonts=[];const old=CanvasRenderingContext2D.prototype.fillText;CanvasRenderingContext2D.prototype.fillText=function(t,...a){if(/\d/.test(String(t)))window.numberFonts.push(this.font);return old.call(this,t,...a)}});await p.goto(pathToFileURL(path.resolve('preview.html')).href);await p.waitForFunction(()=>document.fonts.check('16px Manrope'),{},{timeout:10000});await p.waitForFunction(()=>window.stockScene?.quotes.length>0&&window.numberFonts.length>20,{},{timeout:25000});const fonts=await p.evaluate(()=>window.numberFonts);assert(fonts.every(x=>x.includes('Manrope')),fonts.find(x=>!x.includes('Manrope')));assert.deepEqual(errors,[]);await p.locator('canvas').screenshot({path:'d92-manrope.png'});console.log(`PASS Manrope loaded locally; ${fonts.length} numeric canvas labels all use Manrope; packaged font and license present`)}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
